def histogram(test):
    # Initialize an empty dictionary to store the letter frequencies
    dict = {}
    # Split the input string by spaces to get individual letters
    words = test.split()

    # Iterate through each word in the list
    for word in words:
        # If the word is already in the dictionary, increment its count
        if word in dict:
            dict[word] += 1
        # Otherwise, add the word to the dictionary with a count of 1
        else:
            dict[word] = 1

    # Find the maximum frequency in the dictionary
    max_count = max(dict.values())

    # Iterate through the dictionary and create a new dictionary with letters that have the maximum frequency
    dict_new = {k: v for k, v in dict.items() if v == max_count}

    return dict_new
